using McpDotNet;
using System.Threading.Channels;

public class ManagedMcpClient : IDisposable, IAsyncDisposable
{
    private readonly McpClientFactory _factory;
    private readonly ILogger _logger;
    private McpClientSession? _session;
    private readonly SemaphoreSlim _connectionLock = new(1, 1);
    private readonly CancellationTokenSource _cts = new();
    private DateTime _lastActivity;
    private Task? _heartbeatTask;

    public async Task ConnectAsync(string serverUri, TimeSpan timeout = default)
    {
        await _connectionLock.WaitAsync(_cts.Token);
        try
        {
            var config = new McpClientConfig
            {
                TransportType = TransportType.Stdio,
                TransportOptions = new StdioServerTransportOptions
                {
                    Name = serverUri,
                    Command = "dotnet", // or node, python, etc.
                    CommandLine = "run --project " + serverUri,
                    TransportInitializationRetryCount = 3,
                    TransportInitializationRetryDelay = TimeSpan.FromSeconds(2)
                }
            };

            _session = _factory.CreateClient(config);
            await _session.StartAsync(timeout == default ? TimeSpan.FromSeconds(30) : timeout);

            // Capture initialized server capabilities
            _logger.LogInformation("MCP server initialized. Tools: {Tools}, Resources: {Resources}, Prompts: {Prompts}",
                _session.Capabilities.Tools?.Any(),
                _session.Capabilities.Resources?.Any(),
                _session.Capabilities.Prompts?.Any());

            _lastActivity = DateTime.UtcNow;
            StartHeartbeat();
        }
        finally
        {
            _connectionLock.Release();
        }
    }

    private void StartHeartbeat()
    {
        _heartbeatTask = Task.Run(async () =>
        {
            while (!_cts.Token.IsCancellationRequested)
            {
                await Task.Delay(TimeSpan.FromMinutes(5), _cts.Token);
                try
                {
                    await _session?.PingAsync(_cts.Token);
                    _logger.LogDebug("MCP heartbeat OK");
                }
                catch (Exception ex)
                {
                    _logger.LogWarning(ex, "MCP heartbeat failed, attempting reconnection");
                    await ReconnectAsync();
                }
            }
        });
    }

    public async Task ReconnectAsync()
    {
        // Graceful cleanup before reconnect
        if (_session != null)
        {
            await _session.StopAsync();
            _session.Dispose();
            _session = null;
        }

        // Reconnect with exponential backoff
        for (int attempt = 0; attempt < 5; attempt++)
        {
            try
            {
                await ConnectAsync(_currentServerUri);
                _logger.LogInformation("MCP reconnected after {Attempt} attempts", attempt + 1);
                return;
            }
            catch (Exception ex)
            {
                var delay = TimeSpan.FromSeconds(Math.Pow(2, attempt));
                _logger.LogWarning("Reconnect attempt {Attempt} failed, waiting {Delay}s", attempt + 1, delay.TotalSeconds);
                await Task.Delay(delay, _cts.Token);
            }
        }

        throw new InvalidOperationException("Failed to reconnect MCP session after 5 attempts");
    }
}

public class McpLifecycleManager : IHostedService, IDisposable
{
    private readonly ManagedMcpClient _client;
    private readonly ILogger _logger;
    private readonly CancellationTokenSource _shutdownCts = new();

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        // Establish MCP connection at startup
        await _client.ConnectAsync(Environment.GetEnvironmentVariable("MCP_SERVER_URI"));

        // Hook into application shutdown
        AppDomain.CurrentDomain.ProcessExit += OnProcessExit;
        Console.CancelKeyPress += OnCancelKeyPress;
    }

    private void OnProcessExit(object? sender, EventArgs e)
    {
        _logger.LogInformation("Process exit detected, shutting down MCP sessions");
        _shutdownCts.Cancel();
        _client.Dispose();
    }

    private void OnCancelKeyPress(object? sender, ConsoleCancelKeyPressEventArgs e)
    {
        e.Cancel = true;
        _logger.LogInformation("Ctrl+C received, shutting down MCP sessions");
        _shutdownCts.Cancel();
        _client.Dispose();
    }

    public async Task StopAsync(CancellationToken cancellationToken)
    {
        _logger.LogInformation("Stopping MCP client");
        await _client.StopAsync();
        _client.Dispose();
    }

    public void Dispose()
    {
        _shutdownCts.Dispose();
        _client?.Dispose();
    }
}
